SELECT id, order_id, product_id, NTILE(5) OVER (PARTITION BY product_id, order_id ORDER BY quantity, id) AS quantity_bucket, SUM(unit_price) OVER (ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_unit_price, AVG(unit_price) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS unit_price_avg_2 FROM order_items WHERE unit_price <= 140
